/**
 * Bind the static comparison chooser to an explicit allowlist of prebuilt, same-origin routes.
 * State: choices come from escaped build-time JSON; selects remain bound to one product/version pair.
 * Symbol index (generated by tools/update-symbol-index.ts):
 * @@SYMBOL_INDEX_START
 * - interface Choice: line 13
 * - function readChoices: line 17
 * - function options: line 44
 * - function initializeComparisonChooser: line 50
 * @@SYMBOL_INDEX_END
 */
import { comparisonUrl, type ComparisonRequest } from "../lib/comparison";
interface Choice extends ComparisonRequest {
  readonly url: string;
}
/** Narrow the local build-time dataset and reject tampered/external navigation targets. */
function readChoices(serialized: string): readonly Choice[] {
  const values: unknown = JSON.parse(serialized);
  if (!Array.isArray(values) || values.length > 1000) throw new Error("invalid comparison choices");
  return values.map((value: unknown) => {
    if (typeof value !== "object" || value === null) throw new Error("invalid comparison choice");
    const choice = value as Partial<Choice>;
    if (
      typeof choice.productId !== "string" ||
      typeof choice.from !== "string" ||
      typeof choice.to !== "string" ||
      typeof choice.slug !== "string" ||
      typeof choice.url !== "string"
    )
      throw new Error("invalid comparison choice fields");
    const safe = {
      productId: choice.productId,
      from: choice.from,
      to: choice.to,
      slug: choice.slug,
      url: choice.url,
    };
    if (safe.url !== comparisonUrl(safe) || safe.from === safe.to)
      throw new Error("invalid comparison navigation target");
    return safe;
  });
}
/** Replace select options using text nodes, retaining a previous value only if it remains valid. */
function options(select: HTMLSelectElement, values: readonly string[]): void {
  const previous = select.value;
  select.replaceChildren(...[...new Set(values)].map((value) => new Option(value, value)));
  if (values.includes(previous)) select.value = previous;
}
/** Initialize one chooser; navigation is allowed only to a route that the static build actually emitted. */
export function initializeComparisonChooser(form: HTMLFormElement, serialized: string): void {
  const choices = readChoices(serialized);
  const product = form.querySelector<HTMLSelectElement>("[data-compare-product]");
  const from = form.querySelector<HTMLSelectElement>("[data-compare-from]");
  const to = form.querySelector<HTMLSelectElement>("[data-compare-to]");
  const slug = form.querySelector<HTMLSelectElement>("[data-compare-slug]");
  const status = form.querySelector<HTMLElement>("[data-comparison-status]");
  if (!product || !from || !to || !slug || !status)
    throw new Error("comparison form is incomplete");
  const updateTopics = (): void => {
    options(
      slug,
      choices
        .filter(
          (choice) =>
            choice.productId === product.value &&
            choice.from === from.value &&
            choice.to === to.value,
        )
        .map((choice) => choice.slug),
    );
    status.textContent = "Compare exact editions; missing sections remain explicitly absent.";
  };
  const updateTarget = (): void => {
    options(
      to,
      choices
        .filter((choice) => choice.productId === product.value && choice.from === from.value)
        .map((choice) => choice.to),
    );
    updateTopics();
  };
  const updateProduct = (): void => {
    options(
      from,
      choices.filter((choice) => choice.productId === product.value).map((choice) => choice.from),
    );
    updateTarget();
  };
  product.addEventListener("change", updateProduct);
  from.addEventListener("change", updateTarget);
  to.addEventListener("change", updateTopics);
  form.addEventListener("submit", (event) => {
    event.preventDefault();
    const choice = choices.find(
      (entry) =>
        entry.productId === product.value &&
        entry.from === from.value &&
        entry.to === to.value &&
        entry.slug === slug.value,
    );
    if (choice === undefined) {
      status.textContent = "Choose a documented topic and two distinct versions.";
      return;
    }
    window.location.assign(choice.url);
  });
  updateProduct();
}
